int remount_shmem(struct super_block *sb, int *flags, char *data) {
    struct shmem_config config;
    int ret = 0;

    if (parse_shmem_options(data, &config) < 0)
        return -EINVAL;

    spin_lock(&sb->s_lock);

    if (sb->s_bdev && sb->s_bdev->bd_super != sb)
        sb->s_bdev->bd_super = sb;

    if (config.max_blocks && sb->s_blocks > config.max_blocks) {
        ret = -ENOSPC;
        goto out;
    }

    if (config.max_inodes && sb->s_inodes > config.max_inodes) {
        ret = -ENOSPC;
        goto out;
    }

    sb->s_max_blocks = config.max_blocks;
    sb->s_max_inodes = config.max_inodes;
    sb->s_free_inodes = config.max_inodes;

    if (config.mpolicy) {
        struct mempolicy *pol;
        pol = parse_mempolicy_string(config.mpolicy);
        if (IS_ERR(pol)) {
            ret = PTR_ERR(pol);
            goto out;
        }
        set_mempolicy(sb, pol);
    }

out:
    spin_unlock(&sb->s_lock);
    return ret;
}

int remount_shmem(struct super_block *sb, int *flags, char *data) {
    struct shmem_config new_config;
    int result = parse_shmem_options(data, &new_config);
    if (result < 0)
        return result;

    spin_lock(&sb->s_lock);

    if (sb->s_bdev && sb->s_bdev->bd_inode->i_blocks > new_config.max_blocks) {
        spin_unlock(&sb->s_lock);
        return -EINVAL;
    }

    if (sb->s_files && sb->s_files->i_count > new_config.max_inodes) {
        spin_unlock(&sb->s_lock);
        return -EINVAL;
    }

    sb->s_max_blocks = new_config.max_blocks;
    sb->s_max_inodes = new_config.max_inodes;
    sb->s_free_inodes = new_config.max_inodes;

    if (new_config.policy) {
        mempolicy_set(sb->s_mempolicy, new_config.policy);
    }

    spin_unlock(&sb->s_lock);
    return 0;
}

int remount_shmem(struct super_block *sb, int *flags, char *data) {
    struct shmem_config new_config;
    int ret = 0;

    if (parse_shmem_options(data, &new_config) < 0)
        return -EINVAL;

    spin_lock(&sb->s_lock);

    if (sb->s_inode_count > new_config.max_inodes || sb->s_blocks > new_config.max_blocks) {
        spin_unlock(&sb->s_lock);
        return -EBUSY;
    }

    sb->s_max_inodes = new_config.max_inodes;
    sb->s_max_blocks = new_config.max_blocks;
    sb->s_free_inodes = sb->s_max_inodes - sb->s_inode_count;

    if (new_config.policy) {
        mempolicy_set(&sb->s_policy, new_config.policy);
    }

    spin_unlock(&sb->s_lock);
    return ret;
}

int remount_shmem(struct super_block *sb, int *flags, char *data) {
    struct shmem_config config;
    int ret = 0;
    int blocks, inodes;

    if (parse_shmem_options(data, &config) < 0)
        return -EINVAL;

    down_write(&sb->s_umount);
    lockdep_set_subclass(&sb->s_umount, 1);

    if (sb->s_bdev) {
        if (config.max_blocks < sb->s_blocks_used ||
            config.max_inodes < sb->s_inodes_used) {
            ret = -EINVAL;
            goto out_unlock;
        }
    }

    sb->s_max_blocks = config.max_blocks;
    sb->s_max_inodes = config.max_inodes;
    sb->s_free_inodes = config.max_inodes - sb->s_inodes_used;

    if (config.policy != NULL)
        update_shmem_policy(sb, config.policy);

    out_unlock:
    lockdep_clear_subclass(&sb->s_umount);
    up_write(&sb->s_umount);

    return ret;
}
